    if n == 0:
        return 0

    # Initialize the max product array with the same length as nums
    max_product = [0] * n
    max_product[0] = nums[0]

    # Iterate through the array starting from the second element
    for i in range(1, n):
        # Check all previous elements to find the maximum product subsequence
        for j in range(i):
            if nums[i] > nums[j] and max_product[i] < max_product[j] * nums[i]:
                max_product[i] = max_product[j] * nums[i]

    # Return the maximum value from the max_product array
    return max(max_product)
